package xyz.shuncongci.leica

import org.junit.Assert.*
import org.junit.Test
import java.io.*
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.file.Files
import java.util.concurrent.CancellationException

class EditorMetadataPreservationTest {
    private fun <T> work(run:(File)->T):T{val d=Files.createTempDirectory("editor-metadata-").toFile();return try{run(d)}finally{d.walkBottomUp().forEach{it.delete()}}}
    private fun seg(marker:Int,b:ByteArray)=ByteArrayOutputStream().also{DataOutputStream(it).apply{writeByte(255);writeByte(marker);writeShort(b.size+2);write(b)}}.toByteArray()
    private fun xml(title:String="拍摄说明",extra:String="")="<x:xmpmeta xmlns:x=\"adobe:ns:meta/\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\"><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\"><rdf:Description rdf:about=\"\" xmlns:tiff=\"http://ns.adobe.com/tiff/1.0/\" tiff:Orientation=\"6\" tiff:ImageWidth=\"4096\" dc:title=\"$title\" $extra><dc:creator><rdf:Seq><rdf:li>Fixture Creator</rdf:li></rdf:Seq></dc:creator></rdf:Description></rdf:RDF></x:xmpmeta>".toByteArray()
    private fun iptc():ByteArray {val data=byteArrayOf(0x1c,2,5,0,4)+"Test".toByteArray();return "Photoshop 3.0\u0000".toByteArray()+"8BIM".toByteArray()+byteArrayOf(4,4,0,0)+ByteBuffer.allocate(4).putInt(data.size).array()+data+if(data.size%2!=0)byteArrayOf(0)else byteArrayOf()}
    private fun original(xmp:ByteArray=xml()):ByteArray {val base=CaptureMetadataFixtures.jpeg;return base.copyOfRange(0,2)+seg(0xe1,"Exif\u0000\u0000".toByteArray()+CaptureMetadataFixtures.tiff())+PreservedMetadata.jpegXmp(xmp,emptyList(),16,12).fold(byteArrayOf()){a,b->a+seg(0xe1,b)}+seg(0xed,iptc())+seg(0xfe,"原始注释".toByteArray())+seg(0xe7,"unknown-camera-private".toByteArray())+seg(0xe2,"ICC_PROFILE\u0000\u0001\u0001OLD-P3".toByteArray())+base.copyOfRange(2,base.size)}
    private fun hdr():ByteArray=ByteArrayOutputStream().also{UltraHdrContainer.write(it,CaptureMetadataFixtures.jpeg,CaptureMetadataFixtures.jpeg,HdrMath.Map(16,12,IntArray(192),1f,4f,4f))}.toByteArray()
    private fun testContainer(encoded:ByteArray,source:ByteArray=original(),badge:Boolean=false,check:(File,File,PreservedMetadata.Bundle)->Unit={_,_,_->}){work{d->val origin=File(d,"original").apply{writeBytes(source)};val plain=File(d,"encoded").apply{writeBytes(encoded)};val out=File(d,"output");val bundle=PreservedMetadata.read(origin,Cancel());CaptureMetadataContainer.writePreserved(plain,out,bundle,16,12,badge,Cancel());assertArrayEquals(source,origin.readBytes());assertArrayEquals(encoded,plain.readBytes());val restored=PreservedMetadata.unarchive(PreservedMetadata.readArchive(out,Cancel()));assertEquals(bundle.packets.size,restored.size);bundle.packets.zip(restored).forEach{(a,b)->assertEquals(a.kind,b.kind);assertArrayEquals(a.bytes,b.bytes)};val p=CaptureExif(CaptureMetadataContainer.readExif(out).exif!!);assertEquals("Fixture\u0000",String(p.value(false,0x10f)!!));assertEquals("FixtureLens\u0000",String(p.value(true,0xa434)!!));check(plain,out,bundle)}}
    @Test fun jpegKeepsAllCapturePackets(){testContainer(CaptureMetadataFixtures.jpeg)}
    @Test fun pngKeepsAllCapturePackets(){testContainer(CaptureMetadataFixtures.png)}
    @Test fun webpKeepsAllCapturePackets(){testContainer(CaptureMetadataFixtures.webp)}
    @Test fun losslessWebpKeepsAllCapturePackets(){testContainer(CaptureMetadataFixtures.losslessWebp)}
    @Test fun hdrKeepsAllCapturePackets(){testContainer(hdr())}
    private fun jpegTail(file:File)=RandomAccessFile(file,"r").use{f->val h=CaptureMetadataContainer.jpegHeaders(f);val at=h.last().let{it.offset+it.total};f.seek(at);ByteArray((f.length()-at).toInt()).also{f.readFully(it)}}
    private fun imageChunks(file:File,png:Boolean)=RandomAccessFile(file,"r").use{f->CaptureMetadataContainer.chunks(f,png).filter{it.kind in setOf("IDAT","VP8 ","VP8L","ALPH")}.fold(byteArrayOf()){v,c->f.seek(c.offset);v+ByteArray(c.total.toInt()).also{f.readFully(it)}}}
    @Test fun jpegScanAndGainBytesAreIdentical(){testContainer(hdr()){a,b,_->assertArrayEquals(jpegTail(a),jpegTail(b))}}
    @Test fun pngIdatIsIdentical(){testContainer(CaptureMetadataFixtures.png){a,b,_->assertArrayEquals(imageChunks(a,true),imageChunks(b,true))}}
    @Test fun webpImageChunksAreIdentical(){for(encoded in listOf(CaptureMetadataFixtures.webp,CaptureMetadataFixtures.losslessWebp))testContainer(encoded){a,b,_->assertArrayEquals(imageChunks(a,false),imageChunks(b,false))}}
    @Test fun makerNotesGpsAndUnknownTiffOffsetsSurvive(){testContainer(CaptureMetadataFixtures.jpeg){_,out,b->val before=CaptureExif(b.exif!!);val after=CaptureExif(CaptureMetadataContainer.readExif(out).exif!!);for(tag in listOf(0x927c,0x9286,0xa431,0xa434))assertArrayEquals(before.value(true,tag),after.value(true,tag));before.gps().zip(after.gps()).forEach{(a,c)->assertEquals(a.tag,c.tag);assertArrayEquals(a.raw,c.raw);assertArrayEquals(a.value,c.value)}}}
    @Test fun jpegHasActiveIptcCommentNotOldIcc(){testContainer(CaptureMetadataFixtures.jpeg){_,out,_->val packets=PreservedMetadata.read(out,Cancel(),PreservedMetadata.MAX*3).packets;assertTrue(packets.any{it.kind=="J:ed" && it.bytes.contentEquals(iptc())});assertTrue(packets.any{it.kind=="J:fe"});assertFalse(packets.any{it.kind=="J:e2" && String(it.bytes).contains("OLD-P3")})}}
    @Test fun xmpDescriptionsRemainNativeInEveryFormat(){for(encoded in listOf(CaptureMetadataFixtures.jpeg,CaptureMetadataFixtures.png,CaptureMetadataFixtures.webp))testContainer(encoded){_,out,_->val x=PreservedMetadata.read(out,Cancel(),PreservedMetadata.MAX*3).xmp.joinToString{String(it)};assertTrue(x.contains("拍摄说明"));assertTrue(x.contains("Fixture Creator"));assertTrue(x.contains("tiff:Orientation=\"1\""));assertFalse(x.contains("tiff:Orientation=\"6\""));assertTrue(x.contains("tiff:ImageWidth=\"16\""))}}
    @Test fun extendedXmpIsNotTruncated(){testContainer(CaptureMetadataFixtures.jpeg,original(xml("a".repeat(90000)))){_,out,_->val xmp=PreservedMetadata.read(out,Cancel(),PreservedMetadata.MAX*3).xmp;assertTrue(xmp.any{String(it).contains("a".repeat(90000))})}}
    @Test fun extendedXmpDoesNotHideHdrPrimaryDeclaration(){testContainer(hdr(),original(xml("a".repeat(90000)))){_,out,_->val primary=PreservedMetadata.read(out,Cancel(),PreservedMetadata.MAX*3).xmp.first();assertTrue(String(primary).contains("hdrgm:Version"));assertTrue(String(primary).contains("HasExtendedXMP"))}}
    @Test fun sourceHdrAndMotionOffsetsAreNotActiveInSdr(){val x=xml(extra="xmlns:hdrgm=\"http://ns.adobe.com/hdr-gain-map/1.0/\" hdrgm:Version=\"1.0\" xmlns:GCamera=\"http://ns.google.com/photos/1.0/camera/\" GCamera:MicroVideoOffset=\"12345\"");testContainer(CaptureMetadataFixtures.jpeg,original(x)){_,out,_->val active=PreservedMetadata.read(out,Cancel(),PreservedMetadata.MAX*3).xmp.joinToString{String(it)};assertFalse(active.contains("MicroVideoOffset"));assertFalse(active.contains("hdrgm:Version"))}}
    @Test fun originalHdrMetadataCannotReplaceNewHdr(){val x=xml(extra="xmlns:hdrgm=\"http://ns.adobe.com/hdr-gain-map/1.0/\" hdrgm:Version=\"BAD-SOURCE\"");testContainer(hdr(),original(x)){_,out,_->val active=PreservedMetadata.read(out,Cancel(),PreservedMetadata.MAX*3).xmp.joinToString{String(it)};assertFalse(active.contains("BAD-SOURCE"));assertTrue(active.contains("hdrgm:Version=\"1.0\""))}}
    @Test fun badgeDoesNotReplaceCaptureExif(){testContainer(CaptureMetadataFixtures.jpeg,badge=true){_,out,_->val e=CaptureExif(CaptureMetadataContainer.readExif(out).exif!!);assertEquals(1,e.value(true,XiaomiLeicaBadge.TAG)!![0].toInt()and 1)}}
    @Test fun unsupportedSourceIsExplicitFailure(){work{d->val f=File(d,"source").apply{writeText("fake-heic")};assertThrows(IllegalStateException::class.java){PreservedMetadata.read(f,Cancel())}}}
    @Test fun archiveCorruptionIsRejected(){val b=PreservedMetadata.archive(PreservedMetadata.Bundle(listOf(PreservedMetadata.Packet("test",byteArrayOf(1,2,3))),null,emptyList(),"JPEG"));b[10]=(b[10].toInt() xor 1).toByte();assertThrows(IllegalArgumentException::class.java){PreservedMetadata.unarchive(b)}}
    @Test fun xmpExternalEntitiesAreNeverFetched(){val malicious="<!DOCTYPE foo [<!ENTITY leak SYSTEM 'file:///not-read'>]><x>&leak;</x>".toByteArray();assertThrows(IllegalArgumentException::class.java){PreservedMetadata.mergedXmp(listOf(malicious),emptyList(),16,12)}}
    @Test fun cancellationDoesNotPublishOrChangeOriginal(){work{d->val src=File(d,"original").apply{writeBytes(original())};val bundle=PreservedMetadata.read(src,Cancel());val plain=File(d,"encoded").apply{writeBytes(CaptureMetadataFixtures.jpeg)};val out=File(d,"out");assertThrows(CancellationException::class.java){CaptureMetadataContainer.writePreserved(plain,out,bundle,16,12,false,Cancel().also{it.cancelled=true})};assertFalse(out.exists())}}
    @Test fun existingTargetNeverOverwritten(){work{d->val src=File(d,"original").apply{writeBytes(original())};val bundle=PreservedMetadata.read(src,Cancel());val out=File(d,"out").apply{writeText("user data")};assertThrows(IllegalStateException::class.java){CaptureMetadataContainer.writePreserved(src,out,bundle,16,12,false,Cancel())};assertEquals("user data",out.readText())}}
    private fun gainOffset(file:File):Int=RandomAccessFile(file,"r").use{f->
        val s=CaptureMetadataContainer.jpegHeaders(f).single{it.mpf};val t=CaptureExif(s.payload.copyOfRange(4,s.payload.size));val e=t.root().single{it.tag==0xb002};val at=ByteBuffer.wrap(e.raw).order(t.order).getInt(8)+4;val b=ByteBuffer.wrap(s.payload).order(t.order)
        val size=b.getInt(at+4);val offset=b.getInt(at+24);assertEquals(size.toLong(),s.offset+8+offset);f.seek(size.toLong());assertEquals(0xffd8,f.readUnsignedShort());size
    }
    @Test fun allNewMetadataSizesKeepMpfOffsetsCorrect(){for(title in listOf("small","x".repeat(90000)))testContainer(hdr(),original(xml(title))){plain,out,_->val a=gainOffset(plain);val b=gainOffset(out);assertArrayEquals(plain.readBytes().copyOfRange(a,plain.length().toInt()),out.readBytes().copyOfRange(b,out.length().toInt()))}}
    @Test fun metadataArchiveSurvivesSecondEdit(){testContainer(CaptureMetadataFixtures.jpeg){_,first,_->val b=PreservedMetadata.read(first,Cancel());val second=File(first.parentFile,"second");CaptureMetadataContainer.writePreserved(first,second,b,16,12,false,Cancel());assertArrayEquals(PreservedMetadata.archive(b),PreservedMetadata.readArchive(second,Cancel()))}}
    @Test fun archivePreventsExternalModeFromCallingExifOnlyCopyComplete(){for(bytes in listOf(CaptureMetadataFixtures.jpeg,CaptureMetadataFixtures.png,CaptureMetadataFixtures.webp))testContainer(bytes){_,out,_->assertTrue(CaptureMetadataContainer.readExif(out).otherMetadata)}}
    @Test fun unknownVendorFieldsSurviveEndianDifferences(){for(order in listOf(ByteOrder.BIG_ENDIAN,ByteOrder.LITTLE_ENDIAN)){val src=CaptureExif(CaptureMetadataFixtures.tiff(order));val out=CaptureExif(src.normalized(16,12));assertArrayEquals(src.value(true,0xc123),out.value(true,0xc123));assertArrayEquals(src.value(true,0x927c),out.value(true,0x927c))}}
    @Test fun noExifDoesNotInventCaptureFields(){work{d->val plain=File(d,"p").apply{writeBytes(CaptureMetadataFixtures.png)};val out=File(d,"o");val bundle=PreservedMetadata.read(plain,Cancel());CaptureMetadataContainer.writePreserved(plain,out,bundle,16,12,false,Cancel());assertNull(CaptureExif(CaptureMetadataContainer.readExif(out).exif!!).value(false,0x10f))}}
    @Test fun destinationColorProfileIsNotOverwritten(){val b=CaptureMetadataFixtures.jpeg;val encoded=b.copyOfRange(0,2)+seg(0xe2,"ICC_PROFILE\u0000\u0001\u0001DESTINATION".toByteArray())+b.copyOfRange(2,b.size);testContainer(encoded){_,out,_->val packets=PreservedMetadata.read(out,Cancel(),PreservedMetadata.MAX*3).packets.filter{it.kind=="J:e2"};assertEquals(1,packets.size);assertTrue(String(packets[0].bytes).contains("DESTINATION"))}}
    @Test fun nonSrgbSourceExportDoesNotClaimSrgb(){val x=PreservedMetadata.mergedXmp(listOf(xml()),emptyList(),16,12,false)!!;assertTrue(String(x).contains("exif:ColorSpace=\"65535\""));val e=CaptureExif(CaptureExif(CaptureMetadataFixtures.tiff()).normalized(16,12,outputSrgb=false));assertEquals(65535,ByteBuffer.wrap(e.value(true,0xa001)).order(e.order).short.toInt()and 65535)}
}
